typedef float rational_t;

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator = ( const vector3d& v )
  { x = v.x; y = v.y; z = v.z; return *this; }
  inline T length2() const
  { return x*x + y*y + z*z; }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }
inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }
inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }
inline vector3d::T dot(const vector3d& a, const vector3d& b)
{
  vector3d::T t = a.x*b.x + a.y*b.y + a.z*b.z;
  return t;
}

inline int sgn(float x)
{
  return (x<0)?-1:((x>0)?1:0);
}

class sphere
{
  vector3d center;
  rational_t radius;
public:
  const vector3d& get_center() const { return center; }
  rational_t get_radius() const { return radius; }
};

class portal
{
  char base[172];
  sphere bound;
  rational_t cylinder_depth;
  vector3d normal;
public:
  const vector3d& get_effective_center() const { return bound.get_center(); }
  rational_t get_effective_radius() const { return bound.get_radius(); }
  const vector3d& get_cylinder_normal() const { return normal; }
  bool touches_segment( const vector3d& p1, const vector3d& p2 ) const;
};

bool portal::touches_segment( const vector3d& p1, const vector3d& p2 ) const
{
  vector3d v1 = p1 - get_effective_center();
  vector3d v2 = p2 - get_effective_center();
  rational_t d1 = dot( v1, get_cylinder_normal() );
  rational_t d2 = dot( v2, get_cylinder_normal() );
  // both points on same side of plane?
  if ( sgn(d1) == sgn(d2) )
    return false;
  // check against disc
  v2 = (v2 - v1) * (__builtin_fabsf(d1) / (__builtin_fabsf(d1)+__builtin_fabsf(d2))) + v1;
  return ( v2.length2() < get_effective_radius()*get_effective_radius() );
}
